import json
from pathlib import Path

Path('dist').mkdir(exist_ok=True)

# Explicit model records; feature flags are stored per model, never inferred from iOS.
rows=[]
def add(name, year, ios, source, display, camera, flags='', extra='', battery=None, category='standard'):
    f=set(flags.split())
    r=dict(name='iPhone '+name,year=year,ios=ios,source=source,category=category,
           display=display,camera=camera,extra=extra,battery=battery)
    for key in 'ai uwb magsafe oled usbc faceid esim fiveg promotion lidar island action control satellite modem qi touchid'.split():
        r[key]=key in f
    r['usb']='USB-C · USB 3, up to 10Gb/s' if 'fastusb' in f else ('USB-C · USB 2, up to 480Mb/s' if r['usbc'] else ('30-pin · USB 2' if year<=2011 else 'Lightning · USB 2, up to 480Mb/s'))
    r['sim']='eSIM only' if 'esimonly' in f else ('nano-SIM + eSIM (European version)' if r['esim'] else ('mini-SIM' if year<=2009 else ('micro-SIM' if year<=2011 else 'nano-SIM')))
    rows.append(r)

